  'Workout complete': 'Trening končan', 'kg lifted': 'kg dvignjeno', 'lb lifted': 'lb dvignjeno', 'sets beat': 'izboljšane serije', 'kcal est.': 'kcal ocena', 'Refuel': 'Napolni zaloge', 'Log a meal': 'Vnesi obrok',
